module color_code_finder(input clk, input rst_n, input start, input [3:0] n, input [3:0] p_count, input [3:0][3:0] palette, output reg [15:0] result_valid, output reg [3:0][3:0] next_value, output reg done, output reg impossible); reg [2:0] state; reg [3:0] path [15:0]; reg [15:0] visited; reg [3:0] path_idx; reg [3:0] stack_prev_path_idx [15:0]; reg [3:0] stack_candidate [15:0]; reg [1:0] stack_next_bit [15:0]; reg [3:0] stack_ptr; reg [15:0] result_sequence [15:0]; reg [3:0] seq_idx; reg done_flag, impossible_flag; localparam IDLE=3'd0, INIT=3'd1, DFS_START=3'd2, DFS_STEP=3'd3, CHECK_COMPLETE=3'd4, FOUND=3'd5, IMPOSSIBLE=3'd6; always @(posedge clk) if(!rst_n) state<=IDLE; path<=16'b0; visited<=16'b0; path_idx<=4'd0; stack_ptr<=4'd0; result_sequence<=16'b0; seq_idx<=4'd0; done_flag<=1'b0; impossible_flag<=1'b0; else if(state==IDLE) if(start) state<=INIT; else if(state==INIT) path[0]<=4'b0; visited<= {16'b0,1'b1}; path_idx<=4'd0; state<=DFS_START; else if(state==DFS_START) if(stack_ptr<16) begin stack_prev_path_idx[stack_ptr]<=path_idx; stack_candidate[stack_ptr]<=path[path_idx]; stack_next_bit[stack_ptr]<=2'b00; stack_ptr<=stack_ptr+1; state<=DFS_STEP; end else impossible_flag<=1'b1; state<=IMPOSSIBLE; else if(state==DFS_STEP) if(stack_ptr>0) begin reg [3:0] curr_path=stack_prev_path_idx[stack_ptr-1]; reg [3:0] curr_node=stack_candidate[stack_ptr-1]; reg [1:0] bit=stack_next_bit[stack_ptr-1]; if(bit<n) begin reg [3:0] cand=curr_node^(1<<bit); bit in_p=0; if(p_count>0 && palette[0]==1) in_p=1; if(p_count>1 && !in_p && palette[1]==1) in_p=1; if(p_count>2 && !in_p && palette[2]==1) in_p=1; if(p_count>3 && !in_p && palette[3]==1) in_p=1; if(in_p && cand<(1<<n) && !(visited & (1<<cand))) begin path[path_idx+1]<=cand; visited<=visited|(1<<cand); path_idx<=path_idx+1; if(path_idx==((1<<n)-1)) state<=CHECK_COMPLETE; else if(stack_ptr<16) begin stack_prev_path_idx[stack_ptr]<=path_idx; stack_candidate[stack_ptr]<=cand; stack_next_bit[stack_ptr]<=2'b00; stack_ptr<=stack_ptr+1; state<=DFS_STEP; end else impossible_flag<=1'b1; state<=IMPOSSIBLE; end stack_next_bit[stack_ptr-1]<=bit+1; state<=DFS_STEP; end else begin stack_ptr<=stack_ptr-1; if(stack_ptr>0) begin path_idx<=stack_prev_path_idx[stack_ptr-1]; visited<=visited & ~(1<<stack_candidate[stack_ptr-1]); state<=DFS_STEP; end else impossible_flag<=1'b1; state<=IMPOSSIBLE; end else if(state==CHECK_COMPLETE) state<=FOUND; else if(state==FOUND) if(seq_idx<(1<<n)) begin next_value<=path[seq_idx]; seq_idx<=seq_idx+1; if(seq_idx==(1<<n)) begin result_valid<=1'b1; done_flag<=1'b1; state<=IDLE; end else state<=FOUND; end else begin result_valid<=1'b1; done_flag<=1'b1; state<=IDLE; end else if(state==IMPOSSIBLE) impossible<=1'b1; done<=1'b1; state<=IDLE; assign done = done_flag; assign impossible = impossible_flag; assign result_valid = result_valid; endmodule